class Solution {
  public long maximumMedianSum(int[] nums) {
    Arrays.sort(nums);
    long sum = 0;
    // each step takes the two largest values and the smallest; the median is the second largest
    for (int i = nums.length - 2, steps = nums.length / 3; steps > 0; steps--, i -= 2)
      sum += nums[i];
    return sum;
  }
}
